#!/usr/bin/env python3
"""taskhook — one consistent entry point for launching tasks.

Problem it fixes: ad-hoc, inconsistent launch paths (sometimes ur-wrapped,
sometimes raw; modules assumed present; drained executors unhandled).
Every launch goes through ONE probed path:

  probe  -> pick the healthiest backend -> run with a fail-fast ceiling
         -> record the outcome in the ledger -> fail over on backend failure

Backends are the ACTUAL tools on this box, probed live, never assumed:
  ur-exec   ~/workspace/bin/ur <cmd...>          (introspect+unshare wrapper)
  raw-exec  <cmd...> directly
  python    python3 -c / python3 <script>

Subcommands:
  run [--timeout S] -- <cmd...>   launch; fail over across backends
  health                          live probe of every backend + tool inventory
  ledger [--limit N]              reliability per backend from the ledger
  probe-tools                     enumerate actual internal tool binaries

No fixed sleeps anywhere. Timeouts are fail-fast ceilings (HFT rule:
slow is a kind of wrong — kill the attempt, try the next distinct path).
"""
import argparse, hashlib, json, os, shutil, subprocess, sys, time

HOME = os.path.expanduser("~")
STATE_DIR = os.path.join(HOME, "workspace", "taskhook")
LEDGER = os.path.join(STATE_DIR, "ledger.jsonl")
UR = os.path.join(HOME, "workspace", "bin", "ur")
BR = os.path.join(HOME, "workspace", "bin", "br")
FANOUT = os.path.join(HOME, "workspace", "bin", "fanout")

# Actual internal tool binaries we track (presence + version probe).
TRACKED_TOOLS = [
    ("ur", UR), ("br", BR), ("fanout", FANOUT),
    ("python3", "python3"), ("node", "node"), ("bash", "bash"),
    ("rg", "rg"), ("fd", "fd"), ("jq", "jq"), ("curl", "curl"),
    ("sqlite3", "sqlite3"), ("git", "git"), ("perl", "perl"),
    ("hatch-ws-client", "hatch-ws-client"),
]


def _run_capture(argv, timeout):
    t0 = time.monotonic()
    try:
        p = subprocess.run(argv, capture_output=True, text=True, timeout=timeout)
        return p.returncode, p.stdout, p.stderr, (time.monotonic() - t0) * 1000
    except subprocess.TimeoutExpired as e:
        out = (e.stdout or b"").decode(errors="replace") if isinstance(e.stdout, bytes) else (e.stdout or "")
        err = (e.stderr or b"").decode(errors="replace") if isinstance(e.stderr, bytes) else (e.stderr or "")
        return 124, out, err, (time.monotonic() - t0) * 1000
    except FileNotFoundError as e:
        return 127, "", str(e), (time.monotonic() - t0) * 1000
    except OSError as e:
        return 126, "", str(e), (time.monotonic() - t0) * 1000


def probe_backend(name, timeout=8):
    """Live health probe of one launch backend. Returns dict."""
    if name == "ur-exec":
        if not (os.path.isfile(UR) and os.access(UR, os.X_OK)):
            return {"backend": name, "healthy": False, "reason": "ur missing/not executable"}
        rc, out, err, ms = _run_capture([UR, "true"], timeout)
        return {"backend": name, "healthy": rc == 0, "rc": rc,
                "latency_ms": round(ms, 1), "reason": (err or out).strip()[:200]}
    if name == "raw-exec":
        rc, out, err, ms = _run_capture(["true"], timeout)
        return {"backend": name, "healthy": rc == 0, "rc": rc, "latency_ms": round(ms, 1)}
    if name == "python":
        py = shutil.which("python3")
        if not py:
            return {"backend": name, "healthy": False, "reason": "python3 not found"}
        rc, out, err, ms = _run_capture([py, "-c", "pass"], timeout)
        mods = {}
        for m in ("nest_asyncio",):
            r2, _, _, _ = _run_capture([py, "-c", "import %s" % m], timeout)
            mods[m] = (r2 == 0)
        return {"backend": name, "healthy": rc == 0, "rc": rc,
                "latency_ms": round(ms, 1), "modules": mods}
    return {"backend": name, "healthy": False, "reason": "unknown backend"}


def probe_tools():
    """Enumerate the ACTUAL internal tool binaries on this box."""
    out = []
    for name, path in TRACKED_TOOLS:
        full = path if os.path.isabs(path) else shutil.which(path)
        present = bool(full) and (os.path.isfile(full) if os.path.isabs(full) else True)
        ver = ""
        if present:
            exe = full if os.path.isabs(full) else path
            for flag in ("--version", "-V", "version"):
                rc, so, se, _ = _run_capture([exe, flag], 5)
                txt = (so or se or "").strip().splitlines()
                if rc == 0 and txt:
                    ver = txt[0][:80]
                    break
        out.append({"tool": name, "present": present, "path": full or "", "version": ver})
    return out


def ledger_append(rec):
    os.makedirs(STATE_DIR, exist_ok=True)
    with open(LEDGER, "a") as f:
        f.write(json.dumps(rec) + "\n")


def ledger_read(limit=50):
    if not os.path.isfile(LEDGER):
        return []
    rows = []
    with open(LEDGER) as f:
        for line in f:
            line = line.strip()
            if line:
                try:
                    rows.append(json.loads(line))
                except json.JSONDecodeError:
                    pass
    return rows[-limit:]


def cmd_run(argv, timeout):
    backends = ["ur-exec", "raw-exec"]
    cmd_hash = hashlib.md5(" ".join(argv).encode()).hexdigest()[:12]
    last = None
    for b in backends:
        probe = probe_backend(b)
        if not probe["healthy"]:
            ledger_append({"ts": time.time(), "cmd_hash": cmd_hash, "backend": b,
                           "action": "probe_skip", "reason": probe.get("reason", "")})
            last = probe
            continue
        if b == "ur-exec":
            launch = [UR] + argv
        else:
            launch = argv
        rc, out, err, ms = _run_capture(launch, timeout)
        rec = {"ts": time.time(), "cmd_hash": cmd_hash, "backend": b, "action": "run",
               "rc": rc, "latency_ms": round(ms, 1),
               "probe_latency_ms": probe.get("latency_ms")}
        ledger_append(rec)
        # Fail-fast ceiling: timeout (124) or backend-level failure (126/127)
        # means the BACKEND is broken — fail over to the next distinct path.
        # A nonzero rc from the command itself is the command's own result.
        if rc in (124, 126, 127):
            last = {"backend": b, "rc": rc, "stderr": err[-500:]}
            continue
        sys.stdout.write(out)
        sys.stderr.write(err)
        return rc
    sys.stderr.write("taskhook: all backends failed for cmd_hash=%s last=%s\n"
                     % (cmd_hash, json.dumps(last)[:300]))
    return 99


def cmd_health(_args):
    result = {"ts": time.time(),
              "backends": [probe_backend(b) for b in ("ur-exec", "raw-exec", "python")],
              "tools": probe_tools()}
    print(json.dumps(result, indent=1))


def cmd_ledger(args):
    rows = ledger_read(args.limit)
    by_backend = {}
    for r in rows:
        b = r.get("backend", "?")
        d = by_backend.setdefault(b, {"runs": 0, "ok": 0, "failover": 0, "ms": []})
        if r.get("action") == "run":
            d["runs"] += 1
            if r.get("rc") == 0:
                d["ok"] += 1
            if r.get("rc") in (124, 126, 127):
                d["failover"] += 1
            d["ms"].append(r.get("latency_ms", 0))
        elif r.get("action") == "probe_skip":
            d["failover"] += 1
    for b, d in by_backend.items():
        ms = sorted(d["ms"])
        d["p50_ms"] = round(ms[len(ms) // 2], 1) if ms else 0
        del d["ms"]
    print(json.dumps({"recent": rows[-10:], "by_backend": by_backend}, indent=1))


def main():
    ap = argparse.ArgumentParser(prog="taskhook")
    sub = ap.add_subparsers(dest="cmd", required=True)
    r = sub.add_parser("run")
    r.add_argument("--timeout", type=int, default=60)
    r.add_argument("argv", nargs=argparse.REMAINDER)
    sub.add_parser("health")
    sub.add_parser("probe-tools")
    l = sub.add_parser("ledger")
    l.add_argument("--limit", type=int, default=50)
    args = ap.parse_args()
    if args.cmd == "run":
        argv = args.argv
        if argv and argv[0] == "--":
            argv = argv[1:]
        if not argv:
            sys.stderr.write("taskhook run: no command\n")
            return 2
        return cmd_run(argv, args.timeout)
    if args.cmd == "health":
        return cmd_health(args)
    if args.cmd == "probe-tools":
        print(json.dumps(probe_tools(), indent=1))
        return 0
    if args.cmd == "ledger":
        return cmd_ledger(args)
    return 2


if __name__ == "__main__":
    sys.exit(main() or 0)

