{"command":"python3 -c "
import os, re
# 1. all unix sockets: inode -> path
socks = {}
for line in open('/proc/net/unix').read().splitlines()[1:]:
    parts = line.split()
    inode = parts[6]
    path = parts[7] if len(parts) > 7 else ''
    socks[inode] = path
print('total unix sockets:', len(socks))
# 2. attribute inodes to pids via fd dirs (67 will fail -> stays unattributed)
owned = {}
for pid in os.listdir('/proc'):
    if not pid.isdigit():
        continue
    fd = '/proc/%s/fd' % pid
    try:
        fds = os.listdir(fd)
    except OSError:
        continue
    try:
        with open('/proc/%s/comm' % pid) as f:
            comm = f.read().strip()
    except OSError:
        comm = '?'
    for fn in fds:
        try:
            tgt = os.readlink(os.path.join(fd, fn))
        except OSError:
            continue
        m = re.match(r'socket:\[(\d+)\]', tgt)
        if m:
            owned[m.group(1)] = (pid, comm)
print('attributed:', len(owned))
# 3. unattributed sockets with interesting paths
print('--- unattributed sockets (pid 67 candidates) ---')
n = 0
for inode, path in sorted(socks.items()):
    if inode not in owned and (path.startswith('/run/hatch') or path.startswith('@') or 'hatch' in path):
        print(inode, repr(path))
        n += 1
print('count:', n)
" 2>&1","yield_ms":30000}

