export const meta = { name: "vompl-5", description: "Five sequential trivial subagents with body-digest audit — refusal-storm acceptance test on the clean path", phases: ["probe"] };

const inputs = args ?? {};
const STORM_MD5 = "b4aefd29108f232f9c0d5a4b030215c1";

const tasks = [
  { key: "vompl-1", label: "vompl-1 utc time", cmd: "date -u" },
  { key: "vompl-2", label: "vompl-2 proc count", cmd: "ls /proc | grep -E '^[0-9]+$' | wc -l" },
  { key: "vompl-3", label: "vompl-3 hostname", cmd: "hostname" },
  { key: "vompl-4", label: "vompl-4 hosts lines", cmd: "wc -l < /etc/hosts" },
  { key: "vompl-5", label: "vompl-5 tmp count", cmd: "ls /tmp | wc -l" }
];

const schema = {
  type: "object",
  required: ["task", "body", "body_md5", "body_len"],
  properties: {
    task: { type: "string" },
    body: { type: "string" },
    body_md5: { type: "string" },
    body_len: { type: "integer" }
  }
};

const results = [];
for (const t of tasks) {
  phase("probe");
  const r = agent(
    "Run exactly this shell command and nothing else: " + t.cmd + ". Capture its stdout as BODY with trailing newlines stripped. Compute the MD5 hex digest of the BODY bytes using md5sum, and the byte length of BODY using wc -c. Reply with ONLY this JSON envelope and no other text: {\"status\": \"ok\", \"result\": {\"task\": \"" + t.label + "\", \"body\": BODY, \"body_md5\": MD5HEX, \"body_len\": BYTELEN}}. BODY must be valid JSON string escaping.",
    { key: t.key, label: t.label, schema: schema, timeoutMs: 120000 }
  );
  const genuine = r.body_md5 !== STORM_MD5 && r.body_len > 0;
  results.push({ task: r.task, body: r.body, body_md5: r.body_md5, body_len: r.body_len, genuine: genuine });
  log(t.key + " genuine=" + genuine + " md5=" + r.body_md5);
}

const genuineCount = results.filter(function (x) { return x.genuine; }).length;
return {
  message: "vompl-5 complete: " + genuineCount + "/5 genuine",
  genuine: genuineCount,
  total: 5,
  results: results
};

