        j = bisect.bisect_left(ckpt, h)
        cand = []
        if j < len(ckpt):
            cand.append(abs(h - ckpt[j]))
        if j > 0:
            cand.append(abs(h - ckpt[j - 1]))
        out.append(min(cand) if cand else None)
    return out

